CREATE TABLE public.rent_payment_attempts(payment_attempt_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),rent_record_id UUID NOT NULL REFERENCES public.rent_records(rent_record_id) ON DELETE RESTRICT,tenant_user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE RESTRICT,razorpay_order_id TEXT NOT NULL UNIQUE,razorpay_payment_id TEXT UNIQUE,amount_paise BIGINT NOT NULL CHECK(amount_paise>0),status TEXT NOT NULL DEFAULT 'CREATED' CHECK(status IN('CREATED','PAID','FAILED')),failure_reason TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
ALTER TABLE public.rent_payment_attempts ENABLE ROW LEVEL SECURITY; ALTER TABLE public.rent_payment_attempts FORCE ROW LEVEL SECURITY;
CREATE POLICY rent_payment_attempts_select_own ON public.rent_payment_attempts FOR SELECT TO authenticated USING(tenant_user_id=auth.uid()); REVOKE ALL ON public.rent_payment_attempts FROM PUBLIC,anon,authenticated;
CREATE OR REPLACE FUNCTION public.complete_rent_payment(p_order_id TEXT,p_payment_id TEXT) RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE a public.rent_payment_attempts%ROWTYPE; r public.rent_records%ROWTYPE; BEGIN SELECT * INTO a FROM public.rent_payment_attempts WHERE razorpay_order_id=p_order_id FOR UPDATE; IF NOT FOUND OR a.tenant_user_id<>auth.uid() THEN RAISE EXCEPTION 'Payment attempt not found.'; END IF; SELECT * INTO r FROM public.rent_records WHERE rent_record_id=a.rent_record_id FOR UPDATE; IF a.status='PAID' THEN RETURN; END IF; IF r.status='CANCELLED' THEN RAISE EXCEPTION 'Rent is cancelled.'; END IF; UPDATE public.rent_payment_attempts SET status='PAID',razorpay_payment_id=p_payment_id,failure_reason=NULL,updated_at=NOW() WHERE payment_attempt_id=a.payment_attempt_id; UPDATE public.rent_records SET status='PAID',amount_paid=(a.amount_paise::numeric/100),updated_at=NOW() WHERE rent_record_id=r.rent_record_id; END; $$; GRANT EXECUTE ON FUNCTION public.complete_rent_payment(TEXT,TEXT) TO authenticated;
